/* reconstructed from measured tokens */
body { font-family: "tahoma", Arial, sans-serif; color: #3A3A3A; background: #FAFAFA; }
h1, h2, h3 { font-family: "trebuchet ms", Arial, sans-serif; }
a { color: #2E5785; }
.site-header, .main-menu { background: #2E5785; color: #FFFFFF; }
.footer { background: #2E5785; color: #FFFFFF; }

/* based on real gov.pl markup structure observed in fetched HTML */
body {
  font-family: 'Roboto', Arial, sans-serif;
  color: #1E1E1E;
  background-color: #FFFFFF;
  margin: 0;
}
.top-utility-bar {
  background-color: #00478F;
  color: #FFFFFF;
  font-size: 12px;
  display: flex;
  justify-content: flex-end;
  padding: 4px 16px;
}
.site-header h1 a {
  color: #00478F;
  font-family: 'Roboto Condensed', sans-serif;
  font-weight: 700;
  text-decoration: none;
}
.main-menu {
  background-color: #FFFFFF;
  border-bottom: 2px solid #DC143C;
}
.news-card {
  background-color: #F5F6F7;
  border-radius: 2px;
  overflow: hidden;
}
.news-card time {
  color: #0056A4;
  font-size: 12px;
  font-weight: 600;
}
a { color: #0056A4; }
.footer-govpl { background-color: #00478F; color: #FFFFFF; }

/* based on real markup/structure observed in fetched cba.gov.pl HTML */
body {
  font-family: Arial, Helvetica, sans-serif;
  color: #333333;
  background-color: #FFFFFF;
  margin: 0;
  font-size: 14px;
}
.site-header {
  background-color: #7A0000;
  color: #FFFFFF;
  padding: 14px 20px;
}
.site-header a {
  color: #FFFFFF;
  text-decoration: none;
  font-weight: bold;
}
.accessibility-toolbar {
  background-color: #1B1B1B;
  color: #F0F0F0;
  font-size: 11px;
  padding: 4px 12px;
}
.main-nav {
  background-color: #F0F0F0;
  border-bottom: 3px solid #B22222;
}
.topnews-carousel .headline {
  color: #7A0000;
  font-weight: 700;
}
.report-corruption-cta {
  background-color: #8C1D1D;
  color: #FFFFFF;
  padding: 16px;
  border-radius: 2px;
}
a { color: #8C1D1D; }
.footer { background-color: #1B1B1B; color: #F0F0F0; font-size: 12px; }
